INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("春咲 ひより", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1, 2, 0, 0, 1001, "お！\nあそこに困ってそうな人発見！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("草野 優衣", "みんなみたいに\nわたしも強くならなきゃ", 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", 1, 2, 0, 0, 1002, "大切な人を\n守れるようになりたい…って", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("士条 怜", "フェンシングを始めてみては？", 1, "少しは磨かれると思いますよ。", 1, 2, 0, 0, 1003, "キミに必要な集中力と感性が", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("穂高 みそぎ", "ねぇ、にいちゃん！", 1, "みそぎはねぇ、\nかくれんぼやりたい！", 1, 2, 0, 0, 1004, "今日はなにして遊ぶ？", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("風宮 あかり", "風宮あかりです", 1, "私といっしょに…\nいかない？", 1, 2, 0, 0, 1006, "ねぇ…", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("出雲 宮子", "出雲宮子なのー", 1, "食べ物の恨みは怖いのー", 1, 2, 0, 0, 1007, "プリンたべたいのー", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("虹村 雪", "ボクは虹村雪。", 1, "いいよ。\n見られることは運命さ…", 1, 2, 0, 0, 1008, "キミもボクの美貌に\n吸い寄せられたんだね。", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("柊杏奈", "フッ…聞いて後悔するがいい！", 1, "人呼んで「疾風の冥姫」!!", 1, 2, 0, 0, 1009, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("姫宮 真歩", "マホマホ王国のプリンセス、\nまほ姫どす", 1, "ほんまおおきにやわ～♪", 1, 2, 0, 0, 1010, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("衣之咲 璃乃", "衣之咲璃乃です！", 1, "ここで会ったが\n100年目～！", 1, 2, 0, 0, 1011, "生き別れたお兄ちゃんを探して\n三千世界！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("柏崎 初音", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, "…って、お願い！\n誰にも言わないでおいて～！", 1, 2, 0, 0, 1012, "ち、超能力って…\n何のことかな～？", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("美波 鈴奈", "ちょす！\n美波鈴奈だよ～♪", 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1, 2, 0, 0, 1016, "一応カリスマ読モJKやってまっす！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("喜屋武 香織", "はいたーい。\n喜屋武香織さー。", 1, "でも、沖縄もとってもいいとこさー", 1, 2, 0, 0, 1017, "東京は遊園地みたいなところさー", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("支倉 伊緒", "支倉伊緒です。", 1, "イオちゃんって呼んでね。", 1, 2, 0, 0, 1018, "先生って呼ばれるのは\nくすぐったいから", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("茜 ミミ", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, "ミミをおいてかないでぇ～", 1, 2, 0, 0, 1020, "あ！/\お兄ちゃ～ん\nまってよ～", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("栗林 くるみ", "あ…あの…えっと…\n栗…林…くるみ…です……", 1, "ふぇぇぇぇぇん……", 1, 2, 0, 0, 1021, "あの……\nふぇ……", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("風宮 より", "風宮よりです。\nあああああ！", 1, "なんてありがとうございます！", 1, 2, 0, 0, 1022, "こんな私に貴重な時間を\n割いていただき、", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("北条 綾音", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, "私こっち行きたいー\nね、早く早くー", 1, 2, 0, 0, 1023, "おにいちゃんどこいくの？\nえ？", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("天野 すずめ", "わっ…わっ…私、\n天野すずめといいます！", 1, "これて何か違う…\nあああすみません！", 1, 2, 0, 0, 1025, "ふ、不束者ですが\nどうぞ末永く…って、", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("倉石 恵理子", "……クスクス…私は\n…倉石恵理子……", 1, "離しませんわ………\n絶対に…!!", 1, 2, 0, 0, 1027, "あなたは…運命の……\n伴侶……", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("佐々木 咲恋", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, "…そうでしょ？？", 1, 2, 0, 0, 1028, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("桜井 望", "桜井望だよ！\nよろしくねっ", 1, "あはは、\n私もまだまだだなぁ～", 1, 2, 0, 0, 1029, "ぇっと…\nキミ、私のこと知らないの?!", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ニノン・ジュベール", "デケデケデンっ！", 1, "ショーグン、\nワタシと一緒に天下統一デース！", 1, 2, 0, 0, 1030, "初めまして、\n私はニノン・ジュベール申すデス！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("上喜 しのぶ", "上喜しのぶです。\n手元のドクロが父です。", 1, "おかしいですね……", 1, 2, 0, 0, 1031, "でもって私の隣にいるのが……\nえ、見えない？", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("野戸まひる", "目指すはビッグな\nお笑い芸人だっぺ！", 1, "そう、\nオラのボケに突っ込める相方が…！", 1, 2, 0, 0, 1033, "けんども\nそれには足りないモンが…", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("綾瀬 ゆかり", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, "ちょ\nちょっと一杯飲んできます…！", 1, 2, 0, 0, 1034, "ちょっと緊張しちゃって…", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("氷川 鏡華", "氷川鏡華…です", 1, "これ以上お話しすることは…\nないです！", 1, 2, 0, 0, 1036, "知らない人とは話しちゃいけないので", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("柏崎 栞", "柏崎…栞です。", 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1, 2, 0, 0, 1038, "……あ、アラーム。", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("双葉 碧", "ふ、双葉碧です。", 1, "野に咲く花が、\n唯一の話相手です。", 1, 2, 0, 0, 1040, "私、一人も友達がいなくて……", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("三角 千歌", "三角千歌です。", 1, "そう思っています。", 1, 2, 0, 0, 1042, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("安芸 真琴", "安芸真琴だ。", 1, "う、疑ってすまなかったな…", 1, 2, 0, 0, 1043, "あぁ？\nお前のそいつの仲間か？", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("イリヤ・オーンスタイン", "わらわこそは夜を総べる者！", 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1, 2, 0, 0, 1044, "生けとし生ける全ての者よ！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("遠見 空花", "そこで騎士は妖精を乱暴に……", 1, "ｌク、クウカに何かご用ですか!?", 1, 2, 0, 0, 1045, "ぐふふふふ……はっ！", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("宮坂たまき", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, "う～ん…\n猫ってホントに最高にゃ～♪", 1, 2, 0, 0, 1046, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("大神 美冬", "大神美冬よ！", 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 1, 2, 0, 0, 1048, "それでは早速クエストに…", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("星野静流", "星野静流だよ！", 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1, 2, 0, 0, 1049, "クエストもバトルも\n掃除も洗濯も", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("玉泉美咲", "アタシは玉泉美咲。", 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1, 2, 0, 0, 1050, "見ての通りの\nセクシー美少女で", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("リマ", "？？？", 1, "？？？？", 1, 2, 0, 0, 1052, "？？？？", 1, 0, 0, 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("モニカ・ヴァイスヴィント", "モニカ・ヴァイスヴィントだ。", 1, "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 0, 1053, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ペコリーヌ", "モニカ・ヴァイスヴィントだ。", 1, "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 0, 1058, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 1.5);
