INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("キャル", "モニカ・ヴァイスヴィントだ。", 1, "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 0, 1060, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 1.5);
